#! /usr/bin/env python

# Script to generate Krona plot given a PSI-BLAST output file and (optionally)
# the accessions of the match genes to be plotted. If no accessions are provided,
# generates a Krona plot of all the matches in the PSI-BLAST output file.

# PSI-BLAST output should be the same as that which is generated by
# the AcrVis pipeline:
#   -outfmt "6 qacc sacc pident qlen slen evalue"

import argparse
import os.path as path
from random import randint
import subprocess
import os

parser = argparse.ArgumentParser("Generate Krona plot given PSI-BLAST output generated by the GNAT pipeline and (optionally) the accessions of the match genes to be plotted.")
parser.add_argument("psiblast_outfile", help="Path to the file containing the PSI-BLAST output. Should be in the same format as that which is generated by the GNAT pipeline (-outfmt '6 qacc sacc pident qlen slen evalue')")
parser.add_argument("gb_files", nargs="*", help="Optional space-deliminated genbank GN filenames to generate a Krona plot for. (make sure filenames are in the format generated by GNAT (accession is at filename.split('_')[-2])) If no filenames are provided, a Krona plot of all the matches in the PSI-BLAST output file will be generated. Another important note: the accession in the filename must be present in the PSI-BLAST output file.")
parser.add_argument("-o", "--output", help="Name and location of file to output. Defaults to ./blast.krona.html", default="./blast.krona.html")
parser.add_argument("-k", "--krona", help="Path to ImportBLAST.pl from KronaTools. Defaults to ../Krona/KronaTools/scripts/ImportBLAST.pl", default="../Krona/KronaTools/scripts/ImportBLAST.pl")

args = parser.parse_args()

# Parse psiblast file
if path.exists(args.psiblast_outfile):
    with open(args.psiblast_outfile, "r") as f:
        # Since we have to iterate over the lines here anyway, might
        # as well modify the lines to put them in the format Krona expects
        # 
        # Format:
        # [0] Unique match accession (e.g., RMK91773.1) 
        # [1] Match line with additional pipe (e.g., ./GCA_003698635.1_ASM369863v1_genomic.gbff.gz||MCMZ01000023|RMK91773.1|?|57767|57970|hypothetical)
        # [2-5] Doesn't matter as long as they're tab-separated
        # [6-9] Add additional tab-separated items
        # [10] evalue

        lines = []

        for line in f:
            line = line.strip().split()

            if len(line) != 6:
                print(f"Warning: skipping line of unexpected length ({len(line)}) in PSI-BLAST output file: \n\t{' '.join(line)}")
                continue

            line[0] = line[1].split("|")[2]

            line[1] = ".gz||".join(line[1].split(".gz|"))

            while len(line) < 11:
                line.append(line[-1])

            lines.append(line)

else:
    print(f"Error: provided file '{args.psiblast_outfile}' not found. Please verify the path is correct.")
    exit()

# Parse Krona location
if not path.exists(args.krona):
    print(f"Error: provided path to ImportBLAST.pl '{args.krona}' not found. Please verify the path is correct.")
    exit()
    
if args.gb_files:
    filenames = args.gb_files

    # Pull accessions from filenames
    accessions = [name.strip().split("_")[-2] for name in filenames]

    # Filter PSI-BLAST output lines by the provided accessions
    filtered = []

    # Build a mapping of accessions to line numbers to make it faster to extract them
    accession_map = {}
    for line in range(len(lines)):
        line_accession = lines[line][1].split("|")[3]
        if line_accession in accession_map:
            accession_map[line_accession].append(line) # Handle potential duplicate accessions in output
        else:
            accession_map[line_accession] = [line]

    for accession in accessions:
        if accession in accession_map:
            filtered += [lines[line] for line in accession_map[accession]]
        else:
            print(f"Warning: accession '{accession}' not found in PSI-BLAST output file.")

else:
    # If no accessions specified, filtered is everything
    filtered = lines

# Save filtered in a temp file
temp_name = "tmp_krona"
while path.exists(f"{temp_name}.txt"):
    temp_name += str(randint(0, 99))

temp_name += ".txt"

with open(temp_name, "w") as f:
    f.write("\n".join(["\t".join(line) for line in filtered]))


# Parse output location before running Krona
def iterate_filename(filename):
    """
    Adds an iterative integer to the end of a filename (before the extension) to prevent overwrites.
    :param filename: Str filename (and path) to check if it exists & iterate name if it does
    Return: new filename/location
    """
    if not path.exists(filename):
        return filename

    extension = filename.split('.')[-1]
    filename = '.'.join(filename.split('.')[0:-1])
    i = 0
    while path.exists(f"{filename}_{str(i)}.{extension}"):
        i += 1
    filename = f"{filename}_{str(i)}.{extension}"

    print(f"Warning: Provided output file already exists. Writing to '{filename}' instead.")

    return filename

if path.isdir(args.output):
    # Provided a directory to write to, just use default name
    output = path.join(args.output, "blast.krona.html")
else:
    output = args.output
output = iterate_filename(output)


# Run Krona on the temp file
subprocess.run([args.krona, 
               temp_name,
               "-o", output])

# Remove the temp file
os.remove(temp_name)
